from rdkit import Chem
m = Chem.MolFromMolFile('built.mol', removeHs=False)
for at in m.GetAtoms():
    if at.GetSymbol() in ('Cu','Sb'):
        print(at.GetIdx(), at.GetSymbol(), [n.GetIdx() for n in at.GetNeighbors()], at.GetNumImplicitHs(), at.GetNoImplicit())
# find H atoms and their heavy neighbor
for at in m.GetAtoms():
    if at.GetSymbol()=='H':
        nb = [n.GetIdx() for n in at.GetNeighbors()]
        if nb and nb[0] in (0,1):
            print('H', at.GetIdx(), 'on', nb)
